// Re-render the existing code-authored map with its HTML legend removed.
// NODE_PATH may point at an existing Playwright installation; no new assets
// are painted, cropped, stretched or regenerated by an image model.
const fs=require('fs'),path=require('path'),assert=require('assert/strict');
const {chromium}=require('playwright');
const root=path.resolve(__dirname,'..');
(async()=>{
 const browser=await chromium.launch({channel:'chrome',headless:true});
 try{
  const page=await browser.newPage({viewport:{width:1352,height:1024},deviceScaleFactor:1});
  await page.setContent(fs.readFileSync(path.join(root,'expansion/map/city-map-city-sea-preview-v42.html'),'utf8'));
  await page.evaluate(async()=>{await Promise.all([...document.images].map(i=>i.decode()));document.querySelector('#road-legend').remove();});
  assert.equal(await page.locator('[data-city]').count(),96);
  assert.equal(await page.locator('#road-legend').count(),0);
  await page.screenshot({path:path.join(__dirname,'assets/map-clean.png')});
 }finally{await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
